/// The text of key in lang ("tr" or "en"); the key itself when unknown (visible, and caught by a test).
pub fn t(lang: &str, key: &str) -> String {
    match TEXTS.iter().find(|(k, _, _)| *k == key) {
        Some((_, tr, en)) => (if lang == "en" { *en } else { *tr }).to_string(),
        None => key.to_string(),
    }
}

/// t() with its "{}" replaced.
pub fn tf(lang: &str, key: &str, arg: &str) -> String {
    t(lang, key).replacen("{}", arg, 1)
}

/// t() with each "{}" replaced in turn by the next argument (an argument's own "{}" is never replaced again).
pub fn tn(lang: &str, key: &str, args: &[&str]) -> String {
    let text = t(lang, key);
    let mut out = String::with_capacity(text.len());
    let mut rest = text.as_str();
    let mut args = args.iter();
    while let Some(i) = rest.find("{}") {
        let Some(a) = args.next() else { break };
        out.push_str(&rest[..i]);
        out.push_str(a);
        rest = &rest[i + 2..];
    }
    out.push_str(rest);
    out
}
